			Root<FactorRateMaster> ocpm1 = effectiveDate.from(FactorRateMaster.class);
			effectiveDate.select(cb.max(ocpm1.get("effectiveDateStart")));
			Predicate a1 = cb.equal(ocpm1.get("factorTypeId"), b.get("factorTypeId"));
